CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), username VARCHAR(100) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(30) NOT NULL CHECK (role IN ('super_admin','hr_admin','finance_admin','manager','employee','auditor')), employee_id UUID, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS departments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(120) UNIQUE NOT NULL, code VARCHAR(30) UNIQUE NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employees (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_code VARCHAR(40) UNIQUE NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100), date_of_birth DATE, gender VARCHAR(30), email VARCHAR(255) UNIQUE NOT NULL, phone VARCHAR(30), joining_date DATE NOT NULL, confirmation_date DATE, exit_date DATE, employment_type VARCHAR(30) NOT NULL DEFAULT 'full_time', department_id UUID REFERENCES departments(id), designation VARCHAR(120), manager_id UUID REFERENCES employees(id), pan VARCHAR(20), aadhaar_last4 VARCHAR(4), uan VARCHAR(30), esic_number VARCHAR(40), bank_account_last4 VARCHAR(4), ifsc_code VARCHAR(20), emergency_contact_name VARCHAR(150), emergency_contact_phone VARCHAR(30), status VARCHAR(30) NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive','exited','archived')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_employee_id_fkey;
ALTER TABLE users ADD CONSTRAINT users_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS salary_components (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(120) NOT NULL, component_type VARCHAR(30) NOT NULL CHECK (component_type IN ('earning','deduction','employer_contribution')), calculation_type VARCHAR(30) NOT NULL CHECK (calculation_type IN ('fixed','percentage')), base_component_code VARCHAR(50), percentage NUMERIC(8,4), is_taxable BOOLEAN NOT NULL DEFAULT TRUE, is_statutory BOOLEAN NOT NULL DEFAULT FALSE, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS salary_structures (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE, effective_from DATE NOT NULL, effective_to DATE, ctc_annual NUMERIC(14,2) NOT NULL CHECK (ctc_annual >= 0), notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(employee_id,effective_from));
CREATE TABLE IF NOT EXISTS salary_structure_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), salary_structure_id UUID NOT NULL REFERENCES salary_structures(id) ON DELETE CASCADE, component_id UUID NOT NULL REFERENCES salary_components(id), amount NUMERIC(14,2), percentage NUMERIC(8,4), UNIQUE(salary_structure_id,component_id));
CREATE TABLE IF NOT EXISTS attendance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE, attendance_date DATE NOT NULL, status VARCHAR(20) NOT NULL CHECK (status IN ('present','absent','half_day','wfh','holiday','leave')), check_in TIMESTAMPTZ, check_out TIMESTAMPTZ, overtime_minutes INTEGER NOT NULL DEFAULT 0, source VARCHAR(30) NOT NULL DEFAULT 'manual', UNIQUE(employee_id,attendance_date));
CREATE TABLE IF NOT EXISTS leave_types (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(80) UNIQUE NOT NULL, code VARCHAR(30) UNIQUE NOT NULL, annual_entitlement NUMERIC(8,2) NOT NULL DEFAULT 0, carry_forward BOOLEAN NOT NULL DEFAULT FALSE, is_paid BOOLEAN NOT NULL DEFAULT TRUE, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS leave_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE, leave_type_id UUID NOT NULL REFERENCES leave_types(id), start_date DATE NOT NULL, end_date DATE NOT NULL, days NUMERIC(8,2) NOT NULL, reason TEXT, status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','cancelled')), approved_by UUID REFERENCES users(id), approved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS payroll_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), pay_year INTEGER NOT NULL, pay_month INTEGER NOT NULL CHECK (pay_month BETWEEN 1 AND 12), status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','processing','pending_approval','approved','locked','paid')), prepared_by UUID REFERENCES users(id), approved_by UUID REFERENCES users(id), approved_at TIMESTAMPTZ, locked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(pay_year,pay_month));
CREATE TABLE IF NOT EXISTS payroll_entries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payroll_run_id UUID NOT NULL REFERENCES payroll_runs(id) ON DELETE CASCADE, employee_id UUID NOT NULL REFERENCES employees(id), paid_days NUMERIC(8,2) NOT NULL DEFAULT 0, lop_days NUMERIC(8,2) NOT NULL DEFAULT 0, overtime_hours NUMERIC(8,2) NOT NULL DEFAULT 0, gross_earnings NUMERIC(14,2) NOT NULL DEFAULT 0, total_employee_deductions NUMERIC(14,2) NOT NULL DEFAULT 0, employer_contributions NUMERIC(14,2) NOT NULL DEFAULT 0, net_salary NUMERIC(14,2) NOT NULL DEFAULT 0, calculation_snapshot JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(payroll_run_id,employee_id));
CREATE TABLE IF NOT EXISTS payslips (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payroll_entry_id UUID UNIQUE NOT NULL REFERENCES payroll_entries(id) ON DELETE CASCADE, payslip_number VARCHAR(80) UNIQUE NOT NULL, generated_at TIMESTAMPTZ NOT NULL DEFAULT now(), pdf_sha256 VARCHAR(64));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, actor_user_id UUID REFERENCES users(id), action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id TEXT, old_value JSONB, new_value JSONB, ip_address INET, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_employees_department ON employees(department_id);
CREATE INDEX IF NOT EXISTS idx_attendance_employee_date ON attendance(employee_id,attendance_date);
CREATE INDEX IF NOT EXISTS idx_leave_employee_status ON leave_requests(employee_id,status);
CREATE INDEX IF NOT EXISTS idx_payroll_entries_employee ON payroll_entries(employee_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_entity ON audit_logs(entity_type,entity_id);